#!/bin/bash
# Writes app/Sources/DreamCore/Secrets.swift (git-ignored) from secrets.properties
# (copy secrets.properties.example; every key is optional).
# Missing keys become "" (the app then asks for them in Settings, like the Fire TV build).
set -e
here="$(cd "$(dirname "$0")/.." && pwd)"
props="${1:-$here/secrets.properties}"
get() { [ -f "$props" ] && grep -E "^$1=" "$props" | head -1 | cut -d= -f2- | tr -d '\r' | sed 's/\\/\\\\/g; s/"/\\"/g' || true; }
out="$here/app/Sources/DreamCore/Secrets.swift"
cat > "$out" <<EOF
// Generated by tools/gen-secrets.sh. Never commit this file.
enum BuiltInKeys {
    static let tmdb = "$(get tmdb.key)"
    static let omdb = "$(get omdb.key)"
    static let traktClientId = "$(get trakt.client_id)"
    static let traktClientSecret = "$(get trakt.client_secret)"
}
EOF
echo "wrote $out"
